import raw from '../assets/vessels.json'
import { byName, haystackOf, searchIndex, type IndexEntry } from './structure-index'
import { vesselNames } from './vessel-names'

/**
 * Heart, blood vessels and lymphoid organs exported from Z-Anatomy, named from TA2
 * (assets/vessels.json, generated by tools/anatomy/gen-vessels.mjs). Each entry is a node of
 * vessels.glb or lymph.glb.
 */
export type VesselSet = 'vessels' | 'lymph'
export type VesselKind =
  | 'artery'
  | 'vein'
  | 'pulmonary-artery'
  | 'pulmonary-vein'
  | 'heart'
  | 'valve'
  | 'papillary'
  | 'node'
  | 'organ'
export type Side = 'left' | 'right'

export interface VesselEntry {
  set: VesselSet
  id: string
  kind: VesselKind
  side: Side | null
  en: string
  la: string | null
  es: string | null
  /** TA groups from the nearest up. */
  groups: { en: string; es: string | null }[]
}

/** TA2 names, overridden or completed by the hand-written ones. */
export const vesselEntries = (raw as VesselEntry[]).map((e) => ({
  ...e,
  es: vesselNames[e.en] ?? e.es,
  groups: e.groups.map((g) => ({ ...g, es: vesselNames[g.en] ?? g.es })),
}))
export const vesselById = new Map(vesselEntries.map((e) => [e.id, e]))

/** The index's sections: what the reader looks for, not the model's collections. */
export type Section = 'heart' | 'arteries' | 'veins' | 'lymph'

export const sectionOf = (e: VesselEntry): Section =>
  e.set === 'lymph'
    ? 'lymph'
    : e.kind === 'artery' || e.kind === 'pulmonary-artery'
      ? 'arteries'
      : e.kind === 'vein' || e.kind === 'pulmonary-vein'
        ? 'veins'
        : 'heart'

export const sectionLabel: Record<Section, string> = {
  heart: 'Corazón',
  arteries: 'Arterias',
  veins: 'Venas',
  lymph: 'Órganos linfoides',
}

const capitalize = (s: string) => s.charAt(0).toUpperCase() + s.slice(1)

/** Spanish name, falling back to the TA English name. */
export const vesselName = (e: VesselEntry) => capitalize(e.es ?? e.en)

/**
 * One line of the index: a structure, with both sides together when it is paired
 * ("Arteria cubital" stands for the right and the left one).
 */
export interface IndexItem extends IndexEntry {
  key: string
  section: Section
  name: string
  la: string | null
  en: string
  ids: string[]
  /** Accent-free text the search matches: Spanish, Latin and English names. */
  haystack: string
}

const unsided = (id: string) => id.replace(/-[lr]$/, '')

export const vesselIndex: IndexItem[] = (() => {
  const byKey = new Map<string, IndexItem>()
  for (const e of vesselEntries) {
    const key = unsided(e.id)
    const item = byKey.get(key)
    if (item) {
      item.ids.push(e.id)
      continue
    }
    byKey.set(key, {
      key,
      section: sectionOf(e),
      name: vesselName(e),
      la: e.la,
      en: e.en,
      ids: [e.id],
      haystack: haystackOf(e.es, e.la, e.en),
      title: e.la ?? e.en,
    })
  }
  return [...byKey.values()].sort(byName)
})()

export const indexItemOf = new Map(vesselIndex.flatMap((item) => item.ids.map((id) => [id, item] as const)))

/** Index items whose names contain every word of the query, in any order and without accents. */
export const searchVessels = (query: string, items: IndexItem[] = vesselIndex) => searchIndex(query, items)
